<?php
declare(strict_types=1); session_start();
$config = require __DIR__ . '/config.php'; $error = null;
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    try { $pdo = new PDO(sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4', $config['host'], $config['port'], $config['database']), $config['user'], $config['password'], [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]); $stmt=$pdo->prepare('SELECT id,nombre,email,password_hash,rol,tienda_id FROM usuarios WHERE email=?'); $stmt->execute([trim((string)($_POST['email']??''))]); $user=$stmt->fetch(); if($user && password_verify((string)($_POST['password']??''),$user['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$user['id'],'nombre'=>$user['nombre'],'email'=>$user['email'],'rol'=>$user['rol'],'tienda_id'=>$user['tienda_id']];header('Location: panel.php');exit;} $error='Correo o contraseña incorrectos.'; } catch(Throwable $e){$error='No se pudo iniciar sesión.';}
}
function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ingresar · Galería Cusco</title><style>body{font-family:system-ui;background:#f6f3ee;margin:0}main{max-width:440px;margin:70px auto;padding:20px}.card{background:#fff;padding:28px;border-radius:16px}label{display:block;margin:14px 0 6px}input{box-sizing:border-box;width:100%;padding:11px;border:1px solid #ccc;border-radius:7px}button{margin-top:18px;background:#886c42;color:#fff;border:0;padding:12px 20px;border-radius:8px}</style></head><body><main><p>GALERÍA VIRTUAL CUSCO</p><section class="card"><h1>Ingresar</h1><?php if($error): ?><p><?=h($error)?></p><?php endif; ?><form method="post"><label>Correo</label><input type="email" name="email" required><label>Contraseña</label><input type="password" name="password" required><button>Ingresar</button></form></section></main></body></html>
